import{s as n}from"./supabase.CSz4LLFj.js";async function c(){try{const{data:t,error:s}=await n.from("seat_pool").select("total_seats, claimed_seats").eq("id",1).maybeSingle();if(t&&!s){const a=Math.max(0,t.total_seats-t.claimed_seats),e=document.getElementById("allocation-count"),o=document.getElementById("allocation-bar");if(e&&(e.textContent=`${a.toLocaleString()} / ${t.total_seats.toLocaleString()} available`),o){const l=Math.min(100,Math.max(5,a/t.total_seats*100));o.style.width=`${l}%`}}}catch{}}c();
